#include <iostream>
#include <vector>

int minWeight(const std::vector<int>& ws) {
    int best = ws[0];
    for (int i = 1; i < static_cast<int>(ws.size()); i++) {
        if (ws[i] < best) {
            best = ws[i];
        }
    }
    return best;
}

int maxWeight(const std::vector<int>& ws) {
    int best = ws[0];
    for (int i = 1; i < static_cast<int>(ws.size()); i++) {
        if (ws[i] > best) {
            best = ws[i];
        }
    }
    return best;
}

int span(const std::vector<int>& ws) {
    return maxWeight(ws) - minWeight(ws);
}

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<int> ws(n);
    for (int i = 0; i < n; i++) {
        std::cin >> ws[i];
    }
    std::cout << "最轻 " << minWeight(ws) << "，最重 " << maxWeight(ws) << "，相差 " << span(ws) << " 克" << std::endl;
    return 0;
}
